/**
 * @brief Set the new time interval for the event generation in us.
 * @param handle pointer to the TIMER_EGTM APP configuration.
 * @param time_interval new time interval value in us.
 * @return TIMER_EGTM_STATUS_t: Status of the operation.\n
 *   @ref TIMER_EGTM_STATUS_SUCCESS - Setting new time interval value is successful.\n
 *   @ref TIMER_EGTM_STATUS_FAILURE - New time value is not in range of supported time value or timer is in running condition.\n
 * \par<b>Description</b><br>
 * The period value is updated into the shadow register and shadow transfer request is enabled. Timer has to be stopped before updating the time interval.<br>\n
 * \par<b>Example Usage</b><br>
 * @code
 * #include "Ifx_Types.h"
 * #include "IfxCpu.h"
 * #include "IfxWtu.h"
 * #include "DAVE.h"
 *
 * void core0_main(void)
 * {
 *   IfxCpu_enableInterrupts();
 *   IfxWtu_disableCpuWatchdog(IfxWtu_getCpuWatchdogPassword());
 *   IfxWtu_disableSystemWatchdog(IfxWtu_getSystemWatchdogPassword());
 *
 *   DAVE_STATUS_t status = DAVE_Init();
 *   TIMER_EGTM_STATUS_t timer_status;
 *   if (status == DAVE_STATUS_SUCCESS) {
 *     timer_status = TIMER_EGTM_Stop(&TIMER_EGTM_0);
 *     if (timer_status == TIMER_EGTM_STATUS_SUCCESS) {
 *       timer_status = TIMER_EGTM_SetTimeInterval(&TIMER_EGTM_0, 100000); // Set time interval to 100ms.
 *     }
 *     if (timer_status == TIMER_EGTM_STATUS_SUCCESS) {
 *       timer_status = TIMER_EGTM_Start(&TIMER_EGTM_0);
 *     }
 *   }
 *   while (1U);
 * }
 * @endcode
 */
TIMER_EGTM_STATUS_t TIMER_EGTM_SetTimeInterval(TIMER_EGTM_t *handle, float32 time_interval);

